// Кейс: .qa/tests/monitoring/MON-033.md · план: .qa/e2e-app/specs/app.md (1.47)
// Android, «בדיקת בטיחות», медиа на максимуме в режиме вибрации и беззвучном: НЕТ «עוצמת הקול נמוכה/כבויה», строка просит тестовый звук.
// Тестовый звук НЕ запускается — тест тихий. Режим звонка/громкость возвращаются.
import { assert, openSafetyCheck, withAudio } from '../lib.mjs';

export const name = 'Android «בדיקת בטיחות»: медиа на максимуме в режиме вибрации и в беззвучном → «השמיעו את צליל הבדיקה…», без «עוצמת הקול נמוכה/כבויה» #8edb6e @android @app @prod-safe';

export default async function (app) {
  for (const mode of ['VIBRATE', 'SILENT']) {
    await withAudio(app, { mode, media: 'max' }, async () => {
      await openSafetyCheck(app);
      await app.waitFor('השמיעו את צליל הבדיקה ואשרו ששמעתם אותו', { timeout: 20000, what: `строка «השמיעו את צליל הבדיקה…» (режим ${mode}, медиа max — по adb)` });
      assert(!(await app.exists('עוצמת הקול נמוכה')) && !(await app.exists('עוצמת הקול כבויה')), `в режиме ${mode} при максимуме нет «עוצמת הקול נמוכה/כבויה»`);
      assert(!(await app.exists('העבירו אותו למצב צלצול')), `в режиме ${mode} при максимуме нет подсказки «העבירו אותו למצב צלצול» (громкость уже максимальная)`);
    });
  }
  await app.restart();
}
